-- challenge chal_quiz_javaf_111 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_javaf_111', (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-javaf-1-1' AND is_deleted = false LIMIT 1), 'strings-and-int-arithmetic-quiz', 'Predict the output: == on strings and int overflow', 'Read each snippet the way Java runs it: which strings are the same object, and when does int arithmetic overflow?', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_111'), 'What does this print?

String typed = " book10 ";
String code = typed.strip().toUpperCase();
System.out.println(code == "BOOK10");
System.out.println(code.equals("BOOK10"));
System.out.println("[" + typed + "]");', 'single_choice'::question_type, 'strip() and toUpperCase() each return a NEW String built at runtime, so code is a different object from the "BOOK10" literal: == compares references and prints false, while equals compares the characters and prints true. Strings are immutable: strip() and toUpperCase() never change typed, so it still prints [ book10 ] with its spaces. "true true [BOOK10]" assumes == compares text and that the methods change typed in place; "true true [ book10 ]" gets immutability right but still treats == as a text comparison; "false true [BOOK10]" gets == right but assumes typed was changed.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('true / true / [BOOK10]', false),
        ('true / true / [ book10 ]', false),
        ('false / true / [BOOK10]', false),
        ('false / true / [ book10 ]', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_111'), 'A school orders 25,000 copies of a 120,000 VND textbook:

int copies = 25_000;
int price = 120_000;

Which of these lines store 3000000000 in total? (Select all that apply.)', 'multiple_choice'::question_type, 'int * int is computed in int, and 3,000,000,000 is above Integer.MAX_VALUE (2,147,483,647), so it wraps around to -1294967296 BEFORE any conversion to long happens. That is why long total = copies * price and long total = (long) (copies * price) both store -1294967296: the cast or the assignment widens a result that is already wrong. Casting ONE operand first, (long) copies * price or copies * (long) price, makes the multiplication itself a long multiplication, which gives 3000000000. Math.multiplyExact(copies, price) uses the int version (both arguments are int), so it does not wrap: it throws ArithmeticException: integer overflow. That is safer than a wrong number, but it stores nothing.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('long total = copies * price;', false),
        ('long total = (long) copies * price;', true),
        ('long total = copies * (long) price;', true),
        ('long total = (long) (copies * price);', false),
        ('long total = Math.multiplyExact(copies, price);', false)
    ) AS o(option_text, is_correct);

