-- challenge chal_quiz_javaf_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_javaf_211', (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-javaf-2-1' AND is_deleted = false LIMIT 1), 'list-set-map-quiz', 'Pick the collection, predict the output', 'Choose the right collection for a warehouse scanner and predict what a few common collection calls really do, before you write the restock planner.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_211'), 'The warehouse scanner sends one ISBN per scanned book, so the same ISBN arrives many times. The restock job must (1) answer "did we scan this ISBN tonight?" quickly, tens of thousands of times, and (2) at the end print every scanned ISBN once, in the order it was first scanned. Which declaration fits best?', 'single_choice'::question_type, 'LinkedHashSet is a Set, so add ignores an ISBN that is already there and contains is a hash lookup that does not get slower as the set grows; on top of that it remembers insertion order, so iterating gives the ISBNs in first-scanned order. ArrayList keeps the order but stores every repeat, and contains walks the whole list, so tens of thousands of checks against tens of thousands of ISBNs is hundreds of millions of comparisons. HashSet is unique and fast but makes no promise about iteration order: you would print the ISBNs in hash order. TreeSet is unique too, but it iterates in sorted order (and each lookup is O(log n) instead of a hash lookup), not in the order the books were scanned.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('List<String> scanned = new ArrayList<>();', false),
        ('Set<String> scanned = new HashSet<>();', false),
        ('Set<String> scanned = new LinkedHashSet<>();', true),
        ('Set<String> scanned = new TreeSet<>();', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_211'), 'Which of these statements about Java 21 collections are true? (Select all that apply.)', 'multiple_choice'::question_type, 'Set.of rejects duplicates at creation: Set.of("fiction", "comics", "fiction") throws IllegalArgumentException: duplicate element: fiction. HashSet.add does not throw on a duplicate; it returns false and leaves the set unchanged (true the first time). Integer a = 1000, b = 1000 boxes each value into an Integer object; == compares the two references, and only values from -128 to 127 are cached and shared, so a == b is false (a.equals(b) is true). A TreeMap keeps its keys sorted, so its keySet() prints [comics, fiction, travel], not the insertion order. Map.get returns null for a missing key; getOrDefault("comics", 0) is the call that gives 0.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Set.of("fiction", "comics", "fiction") throws IllegalArgumentException.', true),
        ('Calling add("9786041000011") on a HashSet that already contains that ISBN returns false instead of throwing.', true),
        ('After Integer a = 1000, b = 1000; the expression a == b is true, because both hold 1000.', false),
        ('A TreeMap filled with put("travel", 2), put("comics", 5), put("fiction", 1) prints its keySet() as [travel, comics, fiction].', false),
        ('For a new HashMap<String, Integer>, get("comics") returns 0 because the key is missing.', false)
    ) AS o(option_text, is_correct);

