-- challenge chal_quiz_javaf_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_javaf_311', (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-javaf-3-1' AND is_deleted = false LIMIT 1), 'sealed-switch-guards-dominance-quiz', 'Exhaustive switches, guards and case order', 'Predict what a switch with record patterns and guards returns, and which switch bodies over a sealed interface the compiler accepts.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_311'), 'Mekong Books flags card payments for review. What does this print?

sealed interface Payment permits Card, GiftCard {}
record Card(String last4, long amount) implements Payment {}
record GiftCard(String code, long amount) implements Payment {}

static String check(Payment p) {
    return switch (p) {
        case Card(String last4, long amount) when amount > 1_000_000 -> "review";
        case Card c when c.last4().startsWith("4") -> "visa";
        case Card c -> "card";
        case GiftCard g -> "gift";
    };
}

System.out.println(check(new Card("4242", 2_000_000)) + " "
        + check(new Card("4242", 50_000)) + " "
        + check(new Card("5555", 50_000)) + " "
        + check(new GiftCard("GC-9", 2_000_000)));', 'single_choice'::question_type, 'Cases are tried from top to bottom and the first one whose pattern matches and whose guard is true wins. Card("4242", 2_000_000): the first pattern matches and 2,000,000 > 1,000,000, so "review" (the "visa" case is never reached for it). Card("4242", 50_000): the first guard is false, so matching goes on; "4242" starts with "4", so "visa". Card("5555", 50_000): both guards are false, and the unguarded case Card c catches it: "card". The GiftCard is not a Card, so only case GiftCard g matches, whatever the amount: "gift". The switch compiles: it covers both permitted types, so no default is needed, and both guarded Card cases come before the unguarded one, so nothing is dominated. "visa visa card gift" would need the "4" guard to be checked first; "review review card review" would need the amount guard to apply to every type.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('review visa card gift', true),
        ('visa visa card gift', false),
        ('review review card review', false),
        ('It does not compile: a switch over an interface needs a default case', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_311'), 'Payment is declared as:

sealed interface Payment permits Card, BankTransfer, EWallet {}

Each option is the body of  return switch (p) { ... };  in a method that returns int. Which of them compile with Java 21? (Select all that apply.)', 'multiple_choice'::question_type, 'A compiles: it has one case for each permitted type, so the switch is exhaustive without default. B does not compile: EWallet is not covered, and javac reports "the switch expression does not cover all possible input values". C does not compile: case Card c already matches every Card, so the guarded Card case below it could never run; javac reports "this case label is dominated by a preceding case label". D compiles: the guarded case comes first and the unguarded case Card c catches the cards the guard rejects. E compiles: default covers BankTransfer and EWallet - but it also means the compiler will not warn you when a new type is added, which is exactly what a sealed type is for.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A:  case Card c -> 1;  case BankTransfer b -> 2;  case EWallet e -> 3;', true),
        ('B:  case Card c -> 1;  case BankTransfer b -> 2;', false),
        ('C:  case Card c -> 1;  case Card c when c.amount() > 1_000_000 -> 2;  case BankTransfer b -> 3;  case EWallet e -> 4;', false),
        ('D:  case Card c when c.amount() > 1_000_000 -> 2;  case Card c -> 1;  case BankTransfer b -> 3;  case EWallet e -> 4;', true),
        ('E:  case Card c -> 1;  default -> 0;', true)
    ) AS o(option_text, is_correct);

