-- challenge chal_fix_javaf_321 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_javaf_321', (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-javaf-3-2' AND is_deleted = false LIMIT 1), 'fix-order-page-optional-lookups', 'Stop the order page from crashing on missing data', 'The Mekong Books order page prints one line per (ISBN, customer) query: the title, the price and the shipping city. Real data has holes: delisted ISBNs, unknown customer ids, customers without an address, addresses without a city, and books whose price is missing or 0. A teammate made the lookups return Optional but unwrapped every one with get(), so the page now fails with NoSuchElementException instead of NullPointerException. Fix findBook, findCustomer, shippingCity, priceOf and describe so that every query prints the right line ("Clean Code: 250,000 VND, ship to DA NANG", "9786040000000: not in catalog", "C-99: unknown customer", "C-17: no shipping city") and nothing crashes. A book without its own price uses supplierPrice(isbn), a slow call that the runner counts and prints as the last line: it must count only real fallbacks. The full rules and the input format are in the comment at the top of Main.java.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
