-- challenge chal_quiz_javaf_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_javaf_411', (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-javaf-4-1' AND is_deleted = false LIMIT 1), 'exceptions-flow-quiz', 'Predict the output: catch, finally and try-with-resources', 'Follow an exception the way the JVM does: which catch block runs, when finally runs, in which order resources are closed and what happens to an exception thrown by close().', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_411'), 'What does this program print?

public class Main {
    static String check(String price) {
        try {
            long p = Long.parseLong(price);
            return "ok " + p;
        } catch (NumberFormatException e) {
            return "bad";
        } catch (IllegalArgumentException e) {
            return "illegal";
        } finally {
            System.out.print("[done] ");
        }
    }

    public static void main(String[] args) {
        System.out.println(check("12O000"));
        System.out.println(check("120000"));
    }
}', 'single_choice'::question_type, '"12O000" contains the letter O, so Long.parseLong throws NumberFormatException. Java tries the catch blocks from top to bottom and runs the FIRST one whose type matches; NumberFormatException is listed first, so the result is "bad" (the IllegalArgumentException block would also match, because NumberFormatException is a subclass, but it is never reached). The finally block runs every time the method leaves the try statement, after the return value has been computed but before the caller receives it. So check() prints "[done] " first, and only then does println in main print the returned text: "[done] bad", then "[done] ok 120000". The option with "[done]" at the end of each line has the order backwards: main can only print the result after check() has returned. "illegal" would need the IllegalArgumentException block to come first, which javac would not even compile (exception NumberFormatException has already been caught). And finally is not skipped by return: a return in try or catch still runs finally.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('[done] bad   then   [done] ok 120000', true),
        ('bad [done]   then   ok 120000 [done]', false),
        ('[done] illegal   then   [done] ok 120000', false),
        ('bad   then   ok 120000   (finally is skipped because both blocks return)', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_411'), 'Res prints "open" when it is created and "close" when it is closed, and its close() always throws. What does this print?

public class Main {
    static class Res implements AutoCloseable {
        private final String name;

        Res(String name) {
            this.name = name;
            System.out.println("open " + name);
        }

        @Override
        public void close() {
            System.out.println("close " + name);
            throw new IllegalStateException(name);
        }
    }

    public static void main(String[] args) {
        try (Res a = new Res("A"); Res b = new Res("B")) {
            System.out.println("body " + a.name + b.name);
            throw new RuntimeException("body failed");
        } catch (RuntimeException e) {
            System.out.println("caught " + e.getMessage() + ", suppressed " + e.getSuppressed().length);
        }
    }
}', 'single_choice'::question_type, 'Resources are opened from left to right (A, then B) and closed in the reverse order (B, then A), so a resource is always closed before the ones it may depend on. When the body throws, try-with-resources still closes every resource, even when a close() itself throws: B''s close throws, and A is closed anyway. The exception from the body is the one that propagates to the catch block; each exception thrown by close() is attached to it as a suppressed exception instead of replacing it. So the catch sees "body failed" with 2 suppressed exceptions. Closing in opening order (A before B) is wrong, "caught B" would mean the close exception replaced the real error (that is what a hand-written finally { b.close(); } does), and stopping after B''s failed close would leak A.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_javaf_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('open A | open B | body AB | close B | close A | caught body failed, suppressed 2', true),
        ('open A | open B | body AB | close A | close B | caught body failed, suppressed 2', false),
        ('open A | open B | body AB | close B | close A | caught B, suppressed 0', false),
        ('open A | open B | body AB | close B | caught body failed, suppressed 1', false)
    ) AS o(option_text, is_correct);

