-- challenge chal_coding_javaf_421 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_javaf_421', (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'java21-foundations') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-javaf-4-2' AND is_deleted = false LIMIT 1), 'inventory-report', 'Rebuild the Monday inventory report', 'The Mekong Books warehouse export has one stock line per row: "warehouse;isbn;title;qty;reorderLevel", with ISBNs written with or without hyphens and spaces, blank lines and the odd broken row. Rewrite parse(lineNo, line), classify(qty, reorderLevel) and report(lines): parse each line into a sealed ParseResult (Ok(item) or Bad(lineNo, reason)) without ever stopping on a bad row, merge the same normalised ISBN per warehouse, classify each book as OUT_OF_STOCK, LOW or OK with a switch, list warehouses alphabetically with books sorted by status then title, then a Reorder list with total stock over all warehouses and the rejected lines with their line numbers. report must return an unmodifiable list. The exact rules and output format are in the header comment of Main.java.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
